onSubmit:
{{
  (() => {
    const code = inp_scan_article.text?.trim();
    if (!code) return;

    // 1. Recherche instantanée dans la liste chargée en mémoire
    const data = Get_Articles_Options.data || [];
    const art = data.find(item => 
      (item.Code_Barre && item.Code_Barre.trim().toLowerCase() === code.toLowerCase()) ||
      (item.Ref_Fournisseur && item.Ref_Fournisseur.trim().toLowerCase() === code.toLowerCase()) ||
      (item.value && item.value.toString().toLowerCase() === code.toLowerCase())
    );

    if (art) {
      // 2. Sélection automatique dans le menu déroulant
      storeValue('nouvel_article_id', art.value);
      showAlert('✅ Article trouvé : ' + art.label, 'success');
      resetWidget('inp_scan_article', true);
      storeValue('forceFocus', Date.now());
    } else {
      showAlert('❌ Aucun article trouvé pour : ' + code, 'warning');
      resetWidget('inp_scan_article', true);
      storeValue('forceFocus', Date.now());
    }
  })()
}}
